import re
import logging
import time
from functools import wraps
from taf.hw.switch.hardware import Switch, reconnect_cli_before_executing
from taf.hw.switch.exceptions import GetPortStatusfailure, InvalidPort, GetPortSyncStatefailure


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class NokiaSwitchShellAuthentication(object):

    """
    After SSH connect to switch, will authenticate the switch with under steps:

    Username: admin
    Password:
    Last Login: Tue Aug 17 06:00:55 2021 from ssh_10.57.167.146:38400

    Security compliance warning - Please check password status!

    NOKIA 1830 TPS
    (c) 2019 NOKIA.  All rights reserved.

       Legal Notices  applicable to  any  software   distributed  alone or in
       connection with the product to which this text pertains, are available
       at NOS (Nokia Online Services) with "1830 Time-Sensitive Packet Switch
       (TPS) Software Legal Notice Details".


       This  system   is  restricted  solely to  Nokia  authorized  users for
       legitimate    business  purposes   only.    The actual   or  attempted
       unauthorized  access, use, or modification of this system  is strictly
       prohibited  by  Nokia.  Unauthorized  users  are  subject  to  Company
       disciplinary   proceedings and/or  criminal and  civil penalties under
       state, federal, or other applicable domestic and foreign laws.  Use of
       this  system may  be monitored  and  recorded for  administrative  and
       security reasons.  Anyone accessing this system expressly  consents to
       such  monitoring and is advised  that if  monitoring  reveals possible
       evidence of criminal activity, Nokia may provide  the evidence of such
       activity to law  enforcement  officials.   All  users must comply with
       Nokia   Corporate  Instructions  regarding  the  protection  of  Nokia
       information assets.
    Do you acknowledge? (Y/N)?Y

    Alarm Status:  Critical-13   Major-10   Minor-2   Warning-0
    """

    _AUTHENTICATIONSTEPS = [dict(expectstr="Username:", inputstr="admin"),
                            dict(expectstr="Password:", inputstr="Admin@1830"),
                            dict(expectstr="(Y/N)?", inputstr="Y")]

    def __init__(self, cli, read_timeout=3):
        self._cli = cli
        self._read_timeout = read_timeout

    def run(self):
        for step in self._AUTHENTICATIONSTEPS:
            self._cli.expect_exact(step["expectstr"], self._read_timeout)
            self._cli.sendline(step["inputstr"])


def add_authentication_steps(func):

    """
    Nokia 1830 Tps switch should be authenticated after ssh connected.
    Add authentication step after connect.
    """

    @wraps(func)
    def wrapping_connect_step(self, *args, **kwargs):
        NokiaSwitchShellAuthentication(self._cli).run()
        return func(self, *args, **kwargs)

    return wrapping_connect_step


class Nokia1830Tps(Switch):

    _CONFIG_PORT_COMMAND_TEMPLATE = "config interface {portname} state {status}"
    _SHOW_PORT_COMMAND_TEMPLATE = "show interface {portname}"

    _CONFIG_PORT_SYNC_STATE_COMMAND_TEMPLATE = "config sync 1 ptp clock1 {port} adminState {state}"
    _SHOW_PORT_SYNC_STATE_COMMAND_TEMPLATE = "show sync 1 ptp clock1 {port}"

    _ACTIVE_STATE = "Up"
    _INACTIVE_STATE = "Down"

    _SYNC_UP_STATE = "Up"
    _SYNC_DOWN_STATE = "Down"

    _CONFIG_SYNC_UP_STAET = "up"
    _CONFIG_SYNC_DOWN_STAET = "down"

    _SEARCH_PORT_STATE_REGEX = "Admin State\s+: (Down|Up)"
    _SEARCH_PORT_SYNC_STATE = "adminState\s+:(Down|Up)"

    def __init__(self, *args, **kwargs):
        self._T24EC_PORTS = ["t24ec 1/1/OTC{}".format(portid) for portid in range(1, 9)]

        self._T24PS1_PORTNAMES = ["X{}".format(portid) for portid in range(1, 4)] + ["C{}".format(portid) for portid in range(1, 13)]
        self._T24PS1_PORTS = ["t24ps1 1/{}/{}".format(slot, name) for slot in range(1, 4) for name in self._T24PS1_PORTNAMES]

        self._T24PS2_PORTNAMES = ["X{}".format(portid) for portid in range(1, 4)] + ["C{}".format(portid) for portid in range(1, 13)]
        self._T24PS2_PORTS = ["t24ps2 1/{}/{}".format(slot, name) for slot in range(1, 5) for name in self._T24PS2_PORTNAMES]

        self._T12PS_PORTNAMES = ["X{}".format(portid) for portid in range(1, 3)] + ["C{}".format(portid) for portid in range(1, 13)]
        self._T12PS__PORTS = ["t12ps 1/{}/{}".format(slot, name) for slot in range(1, 4) for name in self._T12PS_PORTNAMES]

        self._port_names = self._T24EC_PORTS + self._T24PS1_PORTS + self._T24PS2_PORTS + self._T12PS__PORTS

        super(Nokia1830Tps, self).__init__(*args, **kwargs)

    def mode_command_type(self, cli):
        pass

    def _read_until_prompt(self):
        pass

    @reconnect_cli_before_executing
    @add_authentication_steps
    def _change_interface_state(self, interface_id, enabled):
        if not self._is_port_valid(interface_id):
            raise InvalidPort(interface_id)

        if enabled:
            config_command = self._create_config_port_up_command(interface_id)
        else:
            config_command = self._create_config_port_down_command(interface_id)
        return self._cli.sendline(config_command)

    @reconnect_cli_before_executing
    @add_authentication_steps
    def interface_active(self, interface_id):
        """ Get the state of the interface (whether it is enabled or not).

        :param interface_id:
            Interface ID as given to the "shutdown" command (e.g. '1/26').
        :type interface_id: ``str``
        :returns: True if interface is enabled, false otherwise.
        :rtype: ``bool``
        """

        return self._ACTIVE_STATE == self._get_port_status(interface_id)

    def _get_port_status(self, port):
        if not self._is_port_valid(port):
            raise InvalidPort(port)

        command = self._create_show_port_command(port)
        self._cli.sendline(command)
        time.sleep(3)
        return self._parse_port_status()

    def _parse_port_status(self):
        """
        # show interface t24ps1 1/3/X3

        Shelf: 1 Slot: 3 Port: X3 - tps24 Line Port [100GbE]
        -------------------------------------------------------------------------------
        Admin State  : Up                 State Qualifier: FLT
        Oper  State  : Down               Oper Capability: Disabled

        Direction    : Bidirectional      Status LED      :  Solid  Red

        Alarm Profile: lbl-port-sysdflt
        """
        show_port_ouput = self._cli.read_nonblocking()
        result = re.search(self._SEARCH_PORT_STATE_REGEX, show_port_ouput)
        if not result:
            raise GetPortStatusfailure(show_port_ouput)
        return result.group(1)

    def _create_config_port_up_command(self, port):
        return self._CONFIG_PORT_COMMAND_TEMPLATE.format(portname=port, status="up")

    def _create_config_port_down_command(self, port):
        return self._CONFIG_PORT_COMMAND_TEMPLATE.format(portname=port, status="down")

    def _create_show_port_command(self, port):
        return self._SHOW_PORT_COMMAND_TEMPLATE.format(portname=port)

    def _is_port_valid(self, port):
        return port in self._port_names

    @reconnect_cli_before_executing
    @add_authentication_steps
    def config_port_sync_up(self, port, wait_time=3):
        port_name = self._construct_port_name(port)
        self._config_port_sync_state(port_name, self._CONFIG_SYNC_UP_STAET)
        state = self._get_port_sync_state(port_name, wait_time)
        return state == self._SYNC_UP_STATE

    @reconnect_cli_before_executing
    @add_authentication_steps
    def config_port_sync_down(self, port, wait_time=3):
        port_name = self._construct_port_name(port)
        self._config_port_sync_state(port_name, self._CONFIG_SYNC_DOWN_STAET)
        state = self._get_port_sync_state(port_name, wait_time)
        return state == self._SYNC_DOWN_STATE

    def _config_port_sync_state(self, port_name, state):
        config_command = self._CONFIG_PORT_SYNC_STATE_COMMAND_TEMPLATE.format(port=port_name, state=state)
        return self._cli.sendline(config_command)

    @reconnect_cli_before_executing
    @add_authentication_steps
    def show_port_sync_state(self, port, wait_time=3):
        port_name = self._construct_port_name(port)
        return self._get_port_sync_state(port_name, wait_time)

    @reconnect_cli_before_executing
    @add_authentication_steps
    def is_port_sync_up(self, port, wait_time=3):
        port_name = self._construct_port_name(port)
        return self._SYNC_UP_STATE == self._get_port_sync_state(port_name, wait_time)

    def _get_port_sync_state(self, port_name, wait_time):
        show_command = self._SHOW_PORT_SYNC_STATE_COMMAND_TEMPLATE.format(port=port_name)
        self._cli.sendline(show_command)
        time.sleep(wait_time)
        return self._parse_port_sync_state()

    def _parse_port_sync_state(self):
        '''
        Then command "show sync 1 ptp clock1 port18"
        The output will like:
            "adminState   :Up"
        '''
        port_sync_state_output = self._cli.read_nonblocking()
        result = re.search(self._SEARCH_PORT_SYNC_STATE, port_sync_state_output)
        if not result:
            raise GetPortSyncStatefailure(port_sync_state_output)
        return result.group(1)

    @staticmethod
    def _construct_port_name(port_number):
        return "port{}".format(port_number)
